import{_ as r,o as a,c as o,a2 as l}from"./chunks/framework.CCCdsIgc.js";const u=JSON.parse('{"title":"项目","description":"","frontmatter":{},"headers":[],"relativePath":"guide/projects.md","filePath":"guide/projects.md"}'),e={name:"guide/projects.md"};function i(n,t,s,p,g,d){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="项目" tabindex="-1">项目 <a class="header-anchor" href="#项目" aria-label="Permalink to &quot;项目&quot;">​</a></h1><p>把一个文件夹建成<strong>项目</strong>，写上目标和说明，之后随时回来接着做。左侧菜单里的「<strong>项目</strong>」就是入口。</p><h2 id="项目是什么" tabindex="-1">项目是什么 <a class="header-anchor" href="#项目是什么" aria-label="Permalink to &quot;项目是什么&quot;">​</a></h2><ul><li>一个项目 = 一个文件夹 + 名称 + 目标 + 补充说明。</li><li>项目里的任务：工作区在这个文件夹里（或它的子文件夹里）的任务，都算这个项目的。</li><li>项目里的任务第一次发消息时，AI 会先看到项目的目标和说明，不用每次重新交代。</li></ul><h2 id="新建项目" tabindex="-1">新建项目 <a class="header-anchor" href="#新建项目" aria-label="Permalink to &quot;新建项目&quot;">​</a></h2><p>左侧「项目」右边的「<strong>+</strong>」，或者项目页右上角的「<strong>新建项目</strong>」：</p><ul><li><strong>名称</strong>：比如「订单系统」。</li><li><strong>您想做什么？</strong>（可选）：项目目标，比如「把下单接口的 p95 延迟降到 200 毫秒以内」。</li><li><strong>放在哪</strong>： <ul><li>新建一个文件夹，放在某个工作区里（下面会显示会新建的完整路径）；</li><li>或者用已有的文件夹（点「选择文件夹并新建」再选）。</li></ul></li><li><strong>补充说明</strong>（可选）：项目约定、背景、要注意的地方，比如「用 pnpm；接口在 api/ 下；不要改数据库结构」。</li></ul><p>目标和说明里不要写密码、令牌。</p><h2 id="在项目里接着做" tabindex="-1">在项目里接着做 <a class="header-anchor" href="#在项目里接着做" aria-label="Permalink to &quot;在项目里接着做&quot;">​</a></h2><p>点开一个项目：</p><ul><li><strong>项目里的任务</strong>：最近的在前，点一下接着做。</li><li><strong>新建任务</strong>：在项目文件夹里开一个新任务。</li><li><strong>在编码模式中打开</strong>（开发者工具打开后才有）：接着这个项目最近的办事任务，直接进编码模式；没有任务就新开一个。</li><li>目标、说明、名称都可以直接改，点「保存」。</li></ul><p>「<strong>从项目列表移除</strong>」只是不在这里显示，文件夹和里面的任务都不会删除。</p><p>项目页右上角可以搜索项目、切换排序（最近打开 / 名称）。</p>',13)])])}const h=r(e,[["render",i]]);export{u as __pageData,h as default};
